/**
 * The sheet's history: each version of its claims, people, rates, settings, periods, statements,
 * patrons, watches, roles, delegations, pools and crews (with their members) a change left, with the sheet's today when the change was
 * made (one removed leaves an empty version). A version is written (by {@link HistoryListener}, in
 * the change's own transaction, so a refused change writes none) only when it differs from the one
 * before it. {@link #asOf} rebuilds the sheet as it stood at the end of a date.
 */
@Service
public class HistoryService {

    private static final String SHEET = "sheet";
    private static final String PERSON = "person";
    private static final String RATE = "rate";
    private static final String CLAIM = "claim";
    private static final String PERIOD = "period";
    private static final String STATEMENT = "statement";
    private static final String PATRON = "patron";
    private static final String WATCH = "watch";
    private static final String ROLE = "role";
    private static final String DELEGATION = "delegation";
    private static final String PERMISSION = "permission";
    private static final String POOL = "pool";
    private static final String POOL_MEMBER = "pool-member";
    private static final String CREW = "crew";
    private static final String CREW_MEMBER = "crew-member";

    /** The version an entity that was removed leaves. */
    private static final String REMOVED = "null";

    record SettingState(String key, LocalDate from, String value) {
    }

    record SheetState(LocalDate policyDate, List<SettingState> settings, LocalDate periodNumberingFrom,
            Integer graceDays, boolean archived, LocalDate entryDate, BigDecimal pot, Integer fiscalStartMonth,
            BigDecimal alertThreshold, Integer escalateAfter, Integer reviewSla, String proofKinds,
            String defaultGrade, Integer scoreMid, Integer scoreHigh, Boolean scoreLog, Integer maxOpen,
            Integer pendingSla) {
    }

    record GradeState(LocalDate from, String grade) {
    }

    record HoldState(LocalDate from, LocalDate to) {
    }

            write(c.getSheetId(), CREW, String.valueOf(c.getId()), new CrewState(c.getName(), c.getLeadId()));
        } else if (entity instanceof CrewMember m) {
            write(sheetOf("crew", m.getCrewId()), CREW_MEMBER, String.valueOf(m.getId()),
                    new CrewMemberState(m.getCrewId(), m.getPersonId()));
        }
    }

    /** The sheet a pool or crew (by its table) is on. */
    private String sheetOf(String table, long id) {
        return jdbc.queryForObject("SELECT sheet_id FROM " + table + " WHERE id = ?", String.class, id);
    }

    /** Write that an entity of the sheet is gone now: a person merged or transferred away (with
     *  their claims), a statement cancelled, a watch stopped, a permission set back to its standing rule,
     *  a pool or crew membership dropped. */
    void removed(Object entity) {
        if (entity instanceof Person p) {
            writeText(p.getSheetId(), PERSON, String.valueOf(p.getId()), REMOVED);
        } else if (entity instanceof Claim c) {
            writeText(c.getSheetId(), CLAIM, String.valueOf(c.getId()), REMOVED);
        } else if (entity instanceof PersonStatement st) {
            writeText(st.getSheetId(), STATEMENT, String.valueOf(st.getId()), REMOVED);
        } else if (entity instanceof PersonPatron pp) {
            writeText(pp.getSheetId(), PATRON, String.valueOf(pp.getId()), REMOVED);
        } else if (entity instanceof PersonWatch w) {
            writeText(w.getSheetId(), WATCH, String.valueOf(w.getId()), REMOVED);
        } else if (entity instanceof SheetDelegation d) {
            writeText(d.getSheetId(), DELEGATION, String.valueOf(d.getId()), REMOVED);
        } else if (entity instanceof SheetRole r) {
            writeText(r.getSheetId(), ROLE, r.getUser(), REMOVED);
        } else if (entity instanceof SheetPermission sp) {
            writeText(sp.getSheetId(), PERMISSION, sp.getAction().key(), REMOVED);
        } else if (entity instanceof PoolMember m) {
            writeText(sheetOf("pool", m.getPoolId()), POOL_MEMBER, String.valueOf(m.getId()), REMOVED);
        } else if (entity instanceof CrewMember m) {
            writeText(sheetOf("crew", m.getCrewId()), CREW_MEMBER, String.valueOf(m.getId()), REMOVED);
        }
    }

    private void write(String sheetId, String kind, String entityId, Object state) {
        writeText(sheetId, kind, entityId, json.writeValueAsString(state));
    }

    private void writeText(String sheetId, String kind, String entityId, String text) {
        List<String> last = jdbc.queryForList(
                "SELECT state FROM history WHERE sheet_id = ? AND kind = ? AND entity_id = ? ORDER BY id DESC LIMIT 1",
                String.class, sheetId, kind, entityId);
        if (!last.isEmpty() && last.get(0).equals(text)) {
            return;
        }
        List<Date> today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
        LocalDate madeOn = today.isEmpty() ? LocalDate.now() : today.get(0).toLocalDate();
        jdbc.update("INSERT INTO history (sheet_id, kind, entity_id, made_on, state) VALUES (?, ?, ?, ?, ?)",
                sheetId, kind, entityId, Date.valueOf(madeOn), text);
    }

    /** The last version of the sheet's history written so far (0 when none). */
    public long lastVersion(String sheetId) {
        Long last = jdbc.queryForObject("SELECT MAX(id) FROM history WHERE sheet_id = ?", Long.class, sheetId);
        return last == null ? 0 : last;
    }
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in list order: by position (the order they were added, unless moved). */
    List<Person> findBySheetIdOrderByPositionAscIdAsc(String sheetId);

    /** The position after the last person's on the sheet: where a new person goes. */
    @Query("select coalesce(max(p.position), 0) + 1 from Person p where p.sheetId = :sheetId")
    long nextPosition(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The sheet's people with this name, ignoring case. */
    List<Person> findBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** The sheet's people with this alias, ignoring case. */
    @Query("select p from Person p join p.aliases a where p.sheetId = :sheetId and lower(a) = lower(:alias)")
    List<Person> findBySheetIdAndAliasIgnoreCase(String sheetId, String alias);

    /** The sheet's person with this name, else with this alias, ignoring case. */
    default Optional<Person> findBySheetIdAndNameOrAlias(String sheetId, String name) {
        return findBySheetIdAndNameIgnoreCase(sheetId, name).stream().findFirst()
                .or(() -> findBySheetIdAndAliasIgnoreCase(sheetId, name).stream().findFirst());
    }

    /** The sheet's people with this contact. */
    List<Person> findBySheetIdAndContact(String sheetId, String contact);

    /** The person, locked so two statements of them are taken one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId")
    Optional<Person> findForUpdate(Long id, String sheetId);
}

